<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'names')); $types=wp_get_post_terms($id,'bsktv_type',array('fields'=>'names')); $room=(float)bsktv_meta('bsktv_room_price'); $head=(float)bsktv_meta('bsktv_head_price'); $table=(float)bsktv_meta('bsktv_table_price'); $host=(float)bsktv_meta('bsktv_host_price'); $manager=(float)bsktv_meta('bsktv_manager_price'); ?>
<main class="single-page"><article>
<header class="store-hero-detail"><div class="store-hero-image"><?php if(has_post_thumbnail())the_post_thumbnail('full',array('fetchpriority'=>'high'));else echo '<div class="store-card-placeholder">BSKTV</div>'; ?><div class="store-hero-overlay"></div></div><div class="container store-hero-content"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">首頁</a><span>/</span><?php echo esc_html(implode('、',$cities)); ?></div><div class="store-kicker"><?php echo esc_html(implode(' · ',$types)); ?></div><h1><?php the_title(); ?></h1><?php if($p=bsktv_meta('bsktv_price'))echo '<div class="hero-price">'.esc_html($p).'</div>'; ?><div class="hero-actions"><button class="btn btn-gold" type="button" data-favorite data-id="'.esc_attr($id).'">♡ 收藏店家</button></div></div></header>
<div class="container section"><div class="single-layout"><div class="article-main"><div class="article-meta"><span>更新於 <?php echo esc_html(get_the_modified_date()); ?></span><span><?php echo esc_html(bsktv_views($id)); ?> 次瀏覽</span></div><div class="article-content"><?php the_content(); ?></div>
<section class="fee-card"><span class="eyebrow">CONSUMPTION</span><h2>消費費用</h2><div class="fee-list"><?php $fees=array('bsktv_room_price'=>'包廂費用','bsktv_host_price'=>'少爺費用','bsktv_manager_price'=>'幹部費用','bsktv_head_price'=>'人頭費用','bsktv_table_price'=>'坐檯費用'); foreach($fees as $key=>$label){$v=(float)bsktv_meta($key);if($v>0)echo '<div class="fee-row"><span>'.esc_html($label).'</span><strong>NT$ '.esc_html(number_format_i18n($v)).'</strong></div>';} ?><div class="fee-note">實際收費依店家現場規定為準。</div></div></section>
<section class="calculator" data-calculator data-room="<?php echo esc_attr($room); ?>" data-head="<?php echo esc_attr($head); ?>" data-table="<?php echo esc_attr($table); ?>" data-host="<?php echo esc_attr($host); ?>" data-manager="<?php echo esc_attr($manager); ?>"><span class="eyebrow">QUICK ESTIMATE</span><h2>消費快速試算</h2><div class="calc-grid"><label>人數<input type="number" min="1" value="2" data-calc-person></label><label>時數<input type="number" min="1" value="2" data-calc-hour></label></div><div class="calc-breakdown"><div><span>底單</span><strong data-calc-base>—</strong></div><div><span>人頭費用</span><strong data-calc-head-total>—</strong></div><div><span>檯費</span><strong data-calc-table-total>—</strong></div></div><div class="calc-result">試算金額 <strong data-calc-result>—</strong></div><small>底單＝包廂費＋少爺費＋幹部費用；人頭費＝人數×人頭費；檯費＝坐檯費×時數。僅為快速估算，實際消費依店家現場規定為準。</small></section>
</div><aside class="store-info"><div class="info-sticky"><div class="info-title"><span class="eyebrow">STORE INFO</span><h2>店家資訊</h2></div><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_model'=>'消費模式','bsktv_room'=>'包廂資訊');foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v)echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span><span>'.esc_html($v).'</span></div>';} ?><a class="btn btn-primary btn-full" href="#line">LINE</a></div></aside></div></div></article><?php get_template_part('template-parts/related'); ?></main><?php endwhile; get_footer(); ?>
